			price:       100.0,
			quantity:    50,
			expected:    3750.0, // 100 * 50 * 0.75
		},
		{
			description: "Quantity 100 (Deep discount)",
			price:       10.0,
			quantity:    100,
			expected:    750.0, // 10 * 100 * 0.75
		},
	}

	// Iterate through tests and validate results
	for _, tc := range tests {
		got := calculateDiscount(tc.price, tc.quantity)

