    process.stdout.write(JSON.stringify(result, null, 2) + '\n');
  } catch (error) {
    // If there is an error, we write it to stderr so stdout remains pure JSON
    if (error instanceof Error) {
      process.stderr.write(`Error: ${error.message}\n`);
    }
    process.exit(1);
  }
}

