	n, err := strconv.Atoi(nStr)
	if err != nil {
		// If input is not a valid integer, exit silently or handle error
		return
	}

	// Find primes using the sieve
	primes := sieveOfEratosthenes(n)

	// Print each prime on a new line
	for _, prime := range primes {
		fmt.Println(prime)
	}
}
